def generate_primes(limit):
    if limit <= 1:
        return []

    # Create a list to store prime numbers
    primes = [2]

    # Check for divisibility starting from 3
    candidate = 3

    while len(primes) < limit:
        is_prime = True

        # If the number is divisible by any prime found so far,
        # it's not prime
        for prime in primes:
            if candidate % prime == 0:
                is_prime = False
                break

        # If the number is prime, add it to the list
        if is_prime:
            primes.append(candidate)

        # Only check odd numbers now (from 3 onwards),
        # as even numbers greater than 2 cannot be prime.
        candidate += 2

    return primes[:limit]

